import{_ as r,l as i,o as e,c as l,v as n,p as s,x as o,d as c,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"Nonce 误用与重放","description":"","frontmatter":{"title":"Nonce 误用与重放","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/nonce-misuse.md","filePath":"cs/nonce-misuse.md","lastUpdated":1789023840000}'),p={name:"cs/nonce-misuse.md"};function E(A,a,_,u,m,f){const t=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=n('<h1 id="nonce-误用与重放" tabindex="-1">Nonce 误用与重放 <a class="header-anchor" href="#nonce-误用与重放" aria-label="Permalink to &quot;Nonce 误用与重放&quot;">​</a></h1><div class="epigraph"><p>Nonce 不是密钥，却必须在同一密钥下唯一。复用一次，CTR/GCM 的证明就退出；重放则是把合法密文再播一次，完整标签拦不住「旧消息再来」。</p><footer>—— 据 NIST SP 800-38D 对 IV 合同；Rogaway 对 nonce-based 加密；Katz and Lindell 整理</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/aead-gcm-internals">GCM 内部</a>把保密与标签收成一次调用。缺口是<strong>状态</strong>：nonce 谁发、如何不重复、重放是否算攻击。主干对称课已警告复用是灾难；本课把它从旁注升为主题。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GCM 在 nonce 复用下会泄漏密钥流并伤及 GHASH 密钥——本课陈述性质，不给恢复步骤。随机 96 比特 nonce 碰撞遵循生日界，消息量大时要换计数器或密钥。重放：敌手重发旧的合法 AEAD 对，标签仍对；要会话层新鲜性（序号、时间窗、<a href="/cs/auth-protocol">认证协议</a>里的 nonce）。</p><h3 id="误用抵抗不是默认" tabindex="-1">误用抵抗不是默认 <a class="header-anchor" href="#误用抵抗不是默认" aria-label="Permalink to &quot;误用抵抗不是默认&quot;">​</a></h3><p>SIV 等误用抵抗模式改变合同：重复 nonce 泄漏相等性而非密钥。不要假设库「已经防呆」。</p><p><span class="marginnote">Rogaway 的 nonce-based 对称加密把唯一性写进游戏。TLS 记录序号、SSH 序号都是协议层计数器。本课不提供复用下的代数求解。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分两条失败：生成端复用；网络重放。对策：计数器 nonce、密钥分级、每连接新密钥、应用层幂等与序号。AEAD 不替代这些。</p>',12)),(e(),s(h,null,{default:o(()=>[d(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEY%5B%22%E5%90%8C%E4%B8%80%E5%AF%86%E9%92%A5%22%5D%20--%3E%20NQ%5B%22nonce%20%E5%BF%85%E9%A1%BB%E5%94%AF%E4%B8%80%22%5D%0A%20%20NQ%20--%3E%20OK%5B%22%E5%90%88%E5%90%8C%E5%86%85%3A%20AEAD%20%E8%AF%81%E6%98%8E%E6%9C%89%E6%95%88%22%5D%0A%20%20NQ%20--%3E%20BAD%5B%22%E5%A4%8D%E7%94%A8%3A%20%E8%AF%81%E6%98%8E%E9%80%80%E5%87%BA%22%5D%0A%20%20OK%20--%3E%20RP%5B%22%E9%87%8D%E6%94%BE%E4%BB%8D%E9%9C%80%E5%BA%8F%E5%8F%B7%2F%E7%AA%97%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>计算安全的证明都有前提。Nonce 是前提里的状态变量。重放是完整性标签范围外的会话语义：标签说「这是某次合法封装」，不说「这是此刻该接受的第一次」。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把随机数硬件写成 CSPRNG 课（更后）。填充预言是另一条主动敌手：下一课说明为何「解密失败如何返回」会变成明文泄漏通道。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GCM 合同的核心是 nonce 唯一。</li><li>复用破坏保密与认证密钥；重放要序号。</li><li>误用抵抗模式是另一合同，不是静默修复。</li><li>下一课：填充与错误信息造成的预言机。</li><li>出处：NIST SP 800-38D；Rogaway；Katz and Lindell；对照 RFC 8446 记录序号。</li></ul>',8))])}const b=r(p,[["render",E]]);export{S as __pageData,b as default};
